#![allow(unused)]
use builtin::*;
use vstd::*;

// We specify pre- and post-conditions for solve.
//   a : distance between the two endpoints (>= 0)
//   b : tank capacity (>= 0)
//   f : distance from one endpoint to the station (0 <= f <= a)
//   k : number of one‐way journeys (>= 1)
// Returns:
//   -1 if the trip(s) are impossible under these parameters,
//    0 if no refill at the station is needed,
//    1 if exactly one refill at the station is needed.
//
// The ensures clauses fully characterize the return value in terms
// of the same feasibility conditions used by the code.
#[verifier::requires(
    a >= 0  &&
    b >= 0  &&
    f >= 0  && f <= a &&
    k >= 1
)]
#[verifier::ensures(result >= -1 && result <= 1)]
#[verifier::ensures((result == -1)
    == ( (b as i16) < (f as i16)
       || (b as i16) < ((a as i16) - (f as i16))
       || ((k as i16) > 1 && (b as i16) < (2*(a as i16) - (f as i16)))
      )
)]
#[verifier::ensures((result == 0)
    <==> ( result != -1 && (b as i16) >= (a as i16) )
)]
#[verifier::ensures((result == 1)
    <==> ( result != -1 && (b as i16) <  (a as i16) )
)]
fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    // Upcast to i16 so we don't overflow when computing things like 2*a - f
    let a = a as i16;
    let b = b as i16;
    let f = f as i16;
    let k = k as i16;

    // Impossible if you can't even make it to the station or to the nearer endpoint
    if b < f || b < (a - f) {
        return -1;
    }
    // If more than one trip is required, you must be able to go
    // from one endpoint to the station and then to the other endpoint:
    // which in the worst case is a round‐trip of length 2*a - f.
    if k > 1 && b < (2 * a - f) {
        return -1;
    }

    // If you can hold at least 'a' units of fuel, you never need to refill.
    if b >= a {
        0
    } else {
        // Otherwise exactly one refill is needed.
        1
    }
}